  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Pirfenidone, the highest-similarity analogue, is reported to be rapidly absorbed with high oral bioavailability in humans and nonclinical species, supporting high F for the similarly small N-phenyl heterocycle query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Edaravone, a close pyrazolone analogue, has an absolute oral bioavailability of 57.3% in humans, well above the 20% threshold, directly supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Clobazam, a structurally related N-phenyl heterocycle, has 87-100% oral bioavailability and its absorption is not affected by food, supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Sulphinpyrazone, another N-phenyl heterocycle, showed 90% absolute oral bioavailability in human volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Mavacamten is rapidly absorbed with an estimated oral bioavailability of at least 85% in humans, supporting high F for a small lipophilic heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Mephobarbital had 71-75% absolute oral bioavailability in human volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, neutral N-phenyl pyrazolone (antipyrine-like). The closest quantitative analogue, edaravone, has ~57% absolute oral bioavailability in humans, and the highest-similarity analogue, pirfenidone, is reported as highly bioavailable. Multiple other structurally related drugs show F values of 71-100%. No affirmative threshold-relevant evidence supports F <20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query itself under fed conditions is provided; the fed-state effect is inferred from analogues and physicochemical properties.",
    "A few vague reports describe 'poor' or 'low' bioavailability for some analogues, but they are contradicted by quantitative absolute F measurements and were not used as affirmative low evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

